import * as T from './vendor/three.module.js';
import {generatedMap} from './generated-materials.mjs';
export const FOREST_TRAIL=[[-17,-28],[-24,-29],[-29,-32],[-35,-33]];
export const FOREST_CLEARING={x:-35,z:-33};
export function forestDistance(x,z,points){let best=Infinity;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],dx=b[0]-a[0],dz=b[1]-a[1],u=Math.max(0,Math.min(1,((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz)));best=Math.min(best,Math.hypot(x-a[0]-u*dx,z-a[1]-u*dz));}return best;}
export function createForestUnderstory(scene,height,sites,allowed,rockMaterial,wood){
 const root=new T.Group();root.userData.kind='layered-alpine-understory';scene.add(root);const pose=new T.Object3D(),floorMatrices=[],plants=[[],[],[],[]],rocks=[],limbs=[],roots=[];let seed=9910;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
 for(const site of sites.filter(p=>p.z< -13&&p.z> -48&&p.x> -44&&p.x<33)){
  for(let k=0;k<4;k++){const a=k*1.57+site.x,length=.38+(k%3)*.11;pose.position.set(site.x+Math.cos(a)*length*.5,height(site.x,site.z)+.045,site.z+Math.sin(a)*length*.5);pose.rotation.set(Math.PI/2,0,-a);pose.scale.set(.035,length,.035);pose.updateMatrix();roots.push(pose.matrix.clone());}
  for(let j=0;j<5;j++){const a=j*2.399+rnd(),d=.6+rnd()*1.4,x=site.x+Math.cos(a)*d,z=site.z+Math.sin(a)*d;if(!allowed(x,z))continue;const y=height(x,z),dx=height(x+.2,z)-height(x-.2,z),dz=height(x,z+.2)-height(x,z-.2);pose.position.set(x,y+.025,z);pose.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),new T.Vector3(-dx/.4,1,-dz/.4).normalize());pose.scale.setScalar(.8+rnd()*.8);pose.updateMatrix();floorMatrices.push(pose.matrix.clone());for(let k=0;k<3;k++){pose.position.set(x+(rnd()-.5)*.8,y+.04,z+(rnd()-.5)*.8);pose.rotation.set(0,rnd()*Math.PI*2,(rnd()-.5)*.15);const s=.35+rnd()*.65;pose.scale.set(s,s,s);pose.updateMatrix();plants[(j+k)%4].push(pose.matrix.clone());}}
  if(rnd()<.3){const x=site.x+.5,z=site.z+.6;if(allowed(x,z)){pose.position.set(x,height(x,z)+.13,z);pose.rotation.set(0,rnd()*6,Math.PI/2-.12);pose.scale.set(.045,.9+rnd(),.045);pose.updateMatrix();limbs.push(pose.matrix.clone());}}
  if(rnd()<.18){const x=site.x-.65,z=site.z+.5;if(allowed(x,z)){pose.position.set(x,height(x,z)+.12,z);pose.rotation.set(rnd(),rnd()*6,0);pose.scale.set(.4,.22,.34);pose.updateMatrix();rocks.push(pose.matrix.clone());}}
 }
 const alphaData=new Uint8Array(32*32*4);for(let y=0;y<32;y++)for(let x=0;x<32;x++){const a=Math.max(0,Math.min(1,(1-Math.hypot((x-15.5)/15.5,(y-15.5)/15.5))*4));alphaData.set([255,Math.round(a*255),255,255],(y*32+x)*4);}const alpha=new T.DataTexture(alphaData,32,32);alpha.needsUpdate=true;
 const floorMap=generatedMap('forest-floor'),floorMat=new T.MeshStandardMaterial({color:floorMap?'#ffffff':'#655e3d',map:floorMap,alphaMap:alpha,transparent:true,depthWrite:false,roughness:1,polygonOffset:true,polygonOffsetFactor:-1}),floorGeo=new T.PlaneGeometry(2.4,2.4);floorGeo.rotateX(-Math.PI/2);const floor=new T.InstancedMesh(floorGeo,floorMat,floorMatrices.length);floorMatrices.forEach((m,i)=>floor.setMatrixAt(i,m));floor.receiveShadow=true;floor.userData.kind='soft-forest-floor';root.add(floor);
 plants.forEach((matrices,tile)=>{const geo=new T.PlaneGeometry(tile===3?.6:.55,tile===3?.23:.65,1,3);geo.translate(0,tile===3?.08:.32,0);const map=generatedMap('forest-botany',tile),material=new T.MeshStandardMaterial({map,color:map?'#ffffff':'#6f8248',alphaTest:.55,side:T.DoubleSide,roughness:1});const mesh=new T.InstancedMesh(geo,material,matrices.length*2),turn=new T.Matrix4().makeRotationY(Math.PI/2);matrices.forEach((m,i)=>{mesh.setMatrixAt(i*2,m);mesh.setMatrixAt(i*2+1,m.clone().multiply(turn));});mesh.userData.kind=['forest-ferns','forest-bilberry','forest-sorrel','forest-moss'][tile];mesh.receiveShadow=true;root.add(mesh);});
 const stone=new T.InstancedMesh(new T.IcosahedronGeometry(1,2),rockMaterial,rocks.length);rocks.forEach((m,i)=>stone.setMatrixAt(i,m));stone.userData.kind='forest-mossy-rocks';stone.castShadow=stone.receiveShadow=true;root.add(stone);const fallen=new T.InstancedMesh(new T.CylinderGeometry(.5,1,1,8),wood,limbs.length);limbs.forEach((m,i)=>fallen.setMatrixAt(i,m));fallen.userData.kind='fallen-forest-branches';fallen.castShadow=true;root.add(fallen);const rootWood=new T.InstancedMesh(new T.CylinderGeometry(.35,1,1,7),wood,roots.length);roots.forEach((m,i)=>rootWood.setMatrixAt(i,m));rootWood.userData.kind='exposed-forest-roots';rootWood.receiveShadow=true;root.add(rootWood);root.userData.plants=plants.reduce((n,p)=>n+p.length,0);return root;
}
